actions.script:
const L = (text) => ec.l10n.localize(text)
const setup = ec.service.sync().name('ironstone.CalendarServices.get#CalendarSetup').call()
const defaults = setup.defaults || {}
const today = setup.todayText || ec.l10n.format(ec.user.nowTimestamp, 'yyyy-MM-dd')
startDay = /^\d{4}-\d{2}-\d{2}/.test(String(date || '')) ? String(date).substring(0, 10) : today
const [year, month, day] = startDay.split('-').map(Number)
const dayAfter = (count) => new Date(Date.UTC(year, month - 1, day + count)).toISOString().substring(0, 10)
endDay = dayAfter(13)
// a day's label: its noon in the user's time zone, so the day does not shift
const dayLabel = (text) => ec.l10n.format(ec.l10n.parseTimestamp(String(text).substring(0, 10) + ' 12:00:00.000', 'yyyy-MM-dd HH:mm:ss.SSS'), 'EEE, MMM d')
rangeText = dayLabel(startDay) + ' – ' + dayLabel(endDay)
previousDay = dayAfter(-14)
nextDay = dayAfter(14)
const tasks = showTasks != null && showTasks !== '' ? (showTasks === 'Y' || showTasks === 'true') : !!defaults.showTasks
const calendars = Array.from(setup.calendarList || [])
eventList = []
if (!ec.message.hasError()) {
    const out = ec.service.sync().name('ironstone.CalendarServices.get#CalendarEvents').parameters({start: startDay, end: endDay,
        calendarIds: calendars.filter((cal) => cal.shown !== false).map((cal) => cal.calendarId).join(','),
        hiddenCalendarIds: calendars.filter((cal) => cal.shown === false).map((cal) => cal.calendarId).join(','),
        showDeclined: !!defaults.showDeclined, showTasks: tasks}).call()
    if (!ec.message.hasError()) eventList = Array.from(out.eventList || []).map((event) => {
        const start = String(event.start || ''), end = String(event.end || '')
        const timeText = event.allDay ? L('All day') : start.substring(11, 16) + (event.kind === 'task' ? ' ' + L('due') :
            (end.length > 11 ? ' – ' + (end.substring(0, 10) === start.substring(0, 10) ? end.substring(11, 16) : dayLabel(end) + ' ' + end.substring(11, 16)) : ''))
        return {sortKey: start, dayText: start ? dayLabel(start) : '', timeText: timeText, title: event.title || L('(no title)'),
            eventId: event.workEffortId, isTask: event.kind === 'task', freeBusyOnly: !!event.freeBusyOnly,
            linkInstanceStart: event.instanceStart && event.recurringEventId === event.workEffortId ? event.instanceStart : null,
            location: event.location || '',
            noteText: event.kind === 'task' ? (event.done ? L('Task done') : L('Task')) : event.statusId === 'WeCancelled' ? L('Cancelled')
                : event.partyStatusId === 'WeptOffered' ? L('Invitation') : event.partyStatusId === 'WeptTentative' ? L('Tentative') : (event.recurring ? L('Repeats') : '')}
    }).sort((left, right) => left.sortKey < right.sortKey ? -1 : left.sortKey > right.sortKey ? 1 : 0)
    // the day only on its first event, as an agenda
    let lastDay = null
    for (const event of eventList) { if (event.dayText === lastDay) event.dayText = ''; else lastDay = event.dayText }
}
